import{memberEngagement}from'./engagement.js';
import{RULES}from'./config.js';import{mean,pct,sorted,stdev}from'./stats.js';import{attendanceTrend,compareRecent}from'./attendance.js';import{analyzeRetention}from'./retention.js';import{conversionRates}from'./promotion.js';
const label=(delta,threshold=RULES.healthChange)=>delta==null?'Not enough data':delta>=threshold?'Improving':delta<=-threshold?'Needs attention':'Stable';
export function clubHealth(rows){const trend=attendanceTrend(rows),ret=memberEngagement(rows),data=sorted(rows),comparison=compareRecent(rows),recent=data.filter(r=>comparison.recentIds.includes(r.id)),previous=data.filter(r=>comparison.previousIds.includes(r.id)),c=conversionRates(recent),p=conversionRates(previous);const promotionChange=comparison.available&&c.signupSampleSize===3&&p.signupSampleSize===3?pct(c.signupsPerReach,p.signupsPerReach):null;const consistencyChange=comparison.available?(stdev(previous.map(r=>r.attendance))===0?null:-pct(stdev(recent.map(r=>r.attendance)),stdev(previous.map(r=>r.attendance)))):null;
return{sampleSize:rows.length,components:[{name:'Attendance',label:trend.direction,value:trend.percentChange,unit:'%',definition:'Last three vs previous three attendance averages. ±10% changes the label.'},{name:'Returning turnout',label:label(ret.trend?.percentagePoints??null,5),value:ret.trend?.percentagePoints??null,unit:'percentage points',definition:'Pooled returning-attendee share, last three vs previous three meetings. ±5 percentage points changes the label; not cohort retention.'},{name:'Signup / reach',label:label(promotionChange),value:promotionChange,unit:'%',definition:'Pooled signup/reach ratio, last three vs previous three. All six meetings need signups and positive reach. ±10% changes the label; not attributed conversion.'},{name:'Consistency',label:consistencyChange==null&&comparison.available&&stdev(previous.map(r=>r.attendance))===0&&stdev(recent.map(r=>r.attendance))===0?'Stable':label(consistencyChange),value:consistencyChange,unit:'%',definition:'Reduction in attendance standard deviation between the previous and last three meetings. ±10% changes the label. Lower variation is more consistent, not necessarily healthier.'}],warnings:['Labels use transparent product thresholds, not a universal club-health score.']}}
export function meetingPulse(rows,{meetingId=null,savedPrediction=null}={}){const data=sorted(rows),meeting=meetingId?data.find(r=>r.id===meetingId):data.at(-1);if(!meeting)return{available:false,warnings:['No meeting available.']};const prior=data.filter(r=>r.date<meeting.date),recent=prior.slice(-5);const validSaved=savedPrediction&&savedPrediction.meetingId===meeting.id&&savedPrediction.createdAt<meeting.date&&Number.isFinite(savedPrediction.estimate);const baseline=validSaved?savedPrediction.estimate:mean(recent.map(r=>r.attendance));const signals=[];const reaches=prior.filter(r=>r.reach!=null);if(meeting.reach!=null&&reaches.length>=3)signals.push({name:'Social reach',actual:meeting.reach,baseline:mean(reaches.map(r=>r.reach)),percentChange:pct(meeting.reach,mean(reaches.map(r=>r.reach))),sampleSize:reaches.length});const same=prior.filter(r=>r.type!=null&&r.type===meeting.type);if(same.length>=RULES.group)signals.push({name:`${meeting.type} history`,actual:meeting.attendance,baseline:mean(same.map(r=>r.attendance)),percentChange:pct(meeting.attendance,mean(same.map(r=>r.attendance))),sampleSize:same.length});const ret=analyzeRetention([...prior,meeting]);if(ret.available&&prior.length>=3){const current=ret.perMeeting.at(-1),previous=ret.perMeeting.slice(0,-1).filter(r=>r.returningShare!=null);if(current.returningShare!=null&&previous.length>=3)signals.push({name:'Returning-attendee share',actual:current.returningShare*100,baseline:mean(previous.map(r=>r.returningShare))*100,unit:'%',sampleSize:previous.length})}return{available:baseline!=null,meeting:{id:meeting.id,name:meeting.name,date:meeting.date,attendance:meeting.attendance},actual:meeting.attendance,baseline,baselineLabel:validSaved?'Saved pre-meeting prediction':`Previous ${recent.length} meetings’ average`,percentChange:pct(meeting.attendance,baseline),difference:baseline==null?null:meeting.attendance-baseline,sampleSize:recent.length,signals,warnings:baseline==null?['No meetings on earlier dates are available for a baseline.']:['This compares the meeting only with earlier dates. No retrospective forecast is presented as a pre-meeting prediction.']}}
